  `user_id` bigint NOT NULL COMMENT '下单用户ID',
  `total_price` decimal(10,2) DEFAULT NULL COMMENT '订单总金额(元)',
  `status` int DEFAULT NULL COMMENT '订单状态：0待支付、1已支付、2已发货、3已完成、4已取消、5已评价、6申请退款中、7退款审核中、8已退款',
