--
-- Table structure for table `review_comment`
--

DROP TABLE IF EXISTS `review_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评论ID，自增主键',
  `review_id` bigint NOT NULL COMMENT '主评价id(goods_comment.id)',
  `user_id` bigint NOT NULL COMMENT '评论用户id',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '评论内容',
  `reply_to_user_id` bigint DEFAULT NULL COMMENT '回复的目标用户id(为空则为普通评论)',
  `reply_to_comment_id` bigint DEFAULT NULL COMMENT '回复的评论id(为空则为一级评论)',
  `status` tinyint DEFAULT '1' COMMENT '状态(0删除1正常)',
  `ai_reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'AI审核拒绝原因',
  `manual_reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '人工审核拒绝原因',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '评论时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除(0未删/1已删)',
  `user_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '用户删除(0未删/1已删)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_review_id` (`review_id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `fk_review_comment_reply_user` (`reply_to_user_id`) USING BTREE,
