INSERT INTO `site_content` VALUES (1,'hero_1','carousel','热销家具精选','爆款单品超值低价，好物一站直达',NULL,'/type/0','{\"bg\": \"#f5ece0\", \"cta\": \"立即抢购\", \"tag\": \"🔥 热销爆款\"}',1,1,'2026-07-14 00:17:55',0),(2,'hero_2','carousel','打造你的梦想客厅','真皮沙发 + 茶几成套购买更省心',NULL,'/type/1','{\"bg\": \"#eef1f5\", \"cta\": \"查看客厅系列\", \"tag\": \"🏠 客厅焕新\"}',2,1,'2026-07-14 00:17:33',0),(3,'hero_3','carousel','小智智能帮你选家具','不知道选什么风格？问问 AI 客服小智，获取专业搭配建议',NULL,'/ai-chat','{\"bg\": \"#eefbf5\", \"cta\": \"开始对话\", \"tag\": \"🤖 AI 导购\"}',3,1,'2026-07-31 18:59:11',0),(4,'brand_intro','story','用心打造每一件家具','名城家具城 创立于 2026 年，专注于将自然材质与现代设计完美融合。\n我们相信，好的家具不仅是功能性的存在，更是承载生活记忆与情感的空间伴侣。\n每一件作品背后，都凝聚着匠人对细节的执着与对美的追求。\n\n从最初的三人设计工作室，到如今服务超过 50,000 个家庭，我们始终坚守初心——将自然材质与现代设计完美融合，为每一个家打造可以传承的经典之作。','https://gmc-1007.oss-cn-beijing.aliyuncs.com/site/2026/07/13/9ca4b865e476449787ddae6956145221.jpg','/about','{\"linkText\": \"了解更多关于我们的故事\"}',1,1,'2026-07-14 00:45:51',0),(5,'brand_image','story',NULL,NULL,'https://gmc-1007.oss-cn-beijing.aliyuncs.com/site/2026/07/13/dc7725262bb7466fad64522748713a47.webp',NULL,'{\"border\": \"1px solid rgba(255,255,255,0.1)\", \"bgColor\": \"rgba(255,255,255,0.06)\"}',2,1,'2026-07-14 00:44:55',0),(6,'value_1','story','正品保障','官方授权品牌入驻，所有商品假一赔十',NULL,NULL,'{\"icon\": \"✓\"}',10,1,'2026-07-14 00:15:56',0),(7,'value_2','story','极速发货','工作日 48 小时内安排出库发货',NULL,NULL,'{\"icon\": \"🚚\"}',11,1,'2026-07-14 00:15:56',0),(8,'value_3','story','7 天无理由','收到货后 7 天内支持无理由退换',NULL,NULL,'{\"icon\": \"↩️\"}',12,1,'2026-07-14 00:15:56',0),(9,'value_4','story','AI 智能客服','小智全天候在线提供家具选购建议',NULL,NULL,'{\"icon\": \"🤖\"}',13,1,'2026-07-14 00:15:56',0),(10,'contact_info','contact',NULL,NULL,NULL,NULL,'{\"email\": \"3102777566@qq.com\", \"phone\": \"13486225146\", \"address\": \"河北省石家庄市\", \"emailNote\": \"24小时内回复\", \"phoneNote\": \"周一至周日 9:00 - 21:00\"}',1,1,'2026-07-14 22:17:31',0),(11,'service_1','service','正品保障','官方授权，假一赔十',NULL,NULL,'{\"icon\": \"✅\"}',1,1,'2026-07-14 00:15:56',0),(12,'service_2','service','极速发货','下单后 48 小时内发货',NULL,NULL,'{\"icon\": \"🚚\"}',2,1,'2026-07-14 00:15:56',0),(13,'service_3','service','7 天无理由','收到货不满意随时退',NULL,NULL,'{\"icon\": \"↩️\"}',3,1,'2026-07-14 00:15:56',0),(14,'service_4','service','AI 客服','7×24 小时智能导购在线',NULL,NULL,'{\"icon\": \"🤖\"}',4,1,'2026-07-14 00:15:56',0),(15,'home_categories','label','家具分类','选择你感兴趣的品类',NULL,NULL,NULL,1,1,'2026-07-14 00:28:04',0),(16,'home_products','label','精选好物','用心挑选每一件家具',NULL,NULL,NULL,2,1,'2026-07-14 00:28:04',0),(23,'system_name','brand','名城家具城',NULL,NULL,NULL,'{}',1,1,'2026-07-14 00:45:26',0),(24,'system_tagline','brand','名城家具',NULL,NULL,NULL,'{}',2,1,'2026-07-14 00:45:26',0),(25,'system_logo','brand',NULL,NULL,'https://gmc-1007.oss-cn-beijing.aliyuncs.com/site/2026/07/13/56d8c898e54045319c3092cfc3a12015.jpg',NULL,'{}',3,1,'2026-07-14 00:44:08',0);
